import { ProfilePatch } from './types';

const MAX_NAME = 40;
const MAX_TAGS = 5;
const MAX_TAG = 12;

function invalid(): never {
  throw new Error('invalid profile');
}

// Reads an own data property without invoking getters.
function dataValue(target: object, key: PropertyKey): unknown {
  const desc = Object.getOwnPropertyDescriptor(target, key);
  if (!desc || !('value' in desc)) return invalid();
  return desc.value;
}

function parseName(value: unknown): string | null {
  if (value === null) return null;
  if (typeof value !== 'string') return invalid();
  const trimmed = value.trim();
  if (trimmed.length < 1 || trimmed.length > MAX_NAME) return invalid();
  return trimmed;
}

function parseTags(value: unknown): string[] {
  if (value === null) return [];
  if (!Array.isArray(value)) return invalid();
  if (value.length > MAX_TAGS) return invalid();
  const seen = new Set<string>();
  const result: string[] = [];
  for (let i = 0; i < value.length; i++) {
    const raw = dataValue(value, String(i));
    if (typeof raw !== 'string') return invalid();
    const tag = raw.trim();
    if (tag.length < 1 || tag.length > MAX_TAG || seen.has(tag)) return invalid();
    seen.add(tag);
    result.push(tag);
  }
  return result;
}

export function parseProfile(input: unknown): ProfilePatch {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) return invalid();
  const proto = Object.getPrototypeOf(input);
  if (proto !== Object.prototype && proto !== null) return invalid();
  for (const key of Reflect.ownKeys(input)) {
    if (key !== 'displayName' && key !== 'tags') return invalid();
  }
  let displayName: ProfilePatch['displayName'] = { kind: 'keep' };
  let tags: ProfilePatch['tags'] = { kind: 'keep' };
  if (Object.prototype.hasOwnProperty.call(input, 'displayName')) {
    displayName = { kind: 'set', value: parseName(dataValue(input, 'displayName')) };
  }
  if (Object.prototype.hasOwnProperty.call(input, 'tags')) {
    tags = { kind: 'set', value: parseTags(dataValue(input, 'tags')) };
  }
  return { displayName, tags };
}

